-- 
-- Definition of componentes_detalle
-- 

DROP TABLE IF EXISTS `componentes_detalle`;
CREATE TABLE IF NOT EXISTS `componentes_detalle` (
  `id` int NOT NULL AUTO_INCREMENT,
  `Id_Componente` int NOT NULL,
  `Id_Subcomponente` int NOT NULL,
  `Id_Unidad_Calculada` int NOT NULL DEFAULT '1',
  `Cantidad_Default` int NOT NULL DEFAULT '1',
  `Cantidad_Adicional` int NOT NULL DEFAULT '30',
  `Aplica_Decremento` tinyint NOT NULL DEFAULT '0',
  `elevado` varchar(50) NOT NULL DEFAULT '0',
  `idCorte` int NOT NULL DEFAULT '0',
  `extra` tinyint DEFAULT '0',
  `Medida` int DEFAULT NULL,
  `Cantidad_Adicional_Anch` int DEFAULT NULL,
  `Aplica_Decremento_Anch` tinyint DEFAULT NULL,
  `Mecanizado` int DEFAULT NULL,
  `Asignacion_puertas` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cd_componente` (`Id_Componente`),
  KEY `idx_cd_subcomponente` (`Id_Subcomponente`)
) ENGINE=InnoDB AUTO_INCREMENT=45247 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

